import os, time, requests

BASE = os.getenv("PLUGNOTAS_BASE", "https://api.plugnotas.com.br")  # sandbox: https://api.sandbox.plugnotas.com.br
SESSAO = requests.Session()
SESSAO.headers.update({"x-api-key": os.environ["PLUGNOTAS_API_KEY"]})  # nunca fixe o token no codigo


def chamar(metodo, caminho, **kw):
    """Uma chamada, com retry simples em 5xx e leitura do envelope de erro do PlugNotas."""
    for tentativa in range(4):
        r = SESSAO.request(metodo, BASE + caminho, timeout=60, **kw)
        if r.status_code >= 500 and tentativa < 3:
            time.sleep(2 ** tentativa)
            continue
        if r.status_code == 401:
            raise RuntimeError("token x-api-key invalido para a base " + BASE)
        if not r.ok:
            corpo = r.json() if "json" in r.headers.get("content-type", "") else {"error": {"message": r.text[:300]}}
            raise RuntimeError("HTTP %s: %s" % (r.status_code, corpo.get("error", corpo)))
        return r
    raise RuntimeError("falhou apos as tentativas")


if __name__ == "__main__":
    dados = chamar("GET", "/nfse/cidades").json()
    print(dados)

snippets.typescript:
const BASE = process.env.PLUGNOTAS_BASE ?? "https://api.plugnotas.com.br"; // sandbox: https://api.sandbox.plugnotas.com.br
const API_KEY = process.env.PLUGNOTAS_API_KEY!;            // nunca fixe o token no codigo

async function chamar(metodo: string, caminho: string, init: RequestInit = {}): Promise<Response> {
  for (let tentativa = 0; tentativa < 4; tentativa++) {
    const r = await fetch(BASE + caminho, {
      ...init,
      method: metodo,
      headers: { "x-api-key": API_KEY, ...(init.headers ?? {}) },
    });
    if (r.status >= 500 && tentativa < 3) { await new Promise(s => setTimeout(s, 2 ** tentativa * 1000)); continue; }
    if (r.status === 401) throw new Error("token x-api-key invalido para a base " + BASE);
    if (!r.ok) throw new Error(`HTTP ${r.status}: ${(await r.text()).slice(0, 300)}`);
    return r;
  }
  throw new Error("falhou apos as tentativas");
}

chamar("GET", "/nfse/cidades").then(r => r.json()).then(console.log);

