import { readFile } from "node:fs/promises";

export async function enviar(caminhoArquivo: string, senha: string) {
  const form = new FormData();
  form.append("arquivo", new Blob([await readFile(caminhoArquivo)]), "certificado.pfx");
  form.append("senha", senha);
  return (await chamar("POST", "/certificado", { body: form })).json();
}

